            startTimeMs,
            durationMs,
            summaryJson,
            meeting.date,
            // Using the ISO string as created_at for sorting simply
            meeting.calendarEventId || null,
            meeting.source || "manual",
            meeting.isProcessed ? 1 : 0,
            meeting.summaryStatus || (meeting.isProcessed ? "completed" : "queued"),
            userTitled ? 1 : 0
